pass(x, &y); 
printf(“After calling: x = %d -- y = %d\n”, x, y); 
return 0; 
} 
void pass(int x, int *y) { 
x = x + 10; 
y = y + 10; 
printf(“In pass():  x = %d -- y = %d\n”, x, y); 
} 

